  const dim=ph==='gather'?.42*seg(t,...TL.gather):(ph==='fort'?.42-.15*seg(t,...TL.fort):.42); cx.fillStyle=`rgba(26,10,4,${dim})`; cx.fillRect(-W*2,-H*2,W*5,H*5);
