  cx.rotate(-u*.4); cx.strokeStyle='#fff'; cx.lineCap='round'; for(let i=0;i<12;i++){ const an=(rnd2(i*5.7)-.5)*1.3+(dir>0?0:Math.PI), r0=R*(.6+u*1.6), r1=r0+R*(.5+rnd2(i)*.6)*(1-u); cx.lineWidth=5*(1-u)+1; cx.beginPath(); cx.moveTo(Math.cos(an)*r0/.55,Math.sin(an)*r0/.55); cx.lineTo(Math.cos(an)*r1/.55,Math.sin(an)*r1/.55); cx.stroke(); }
