  if(ph==='intro'){ const u=seg(t,...TL.intro); cz=lerp(1,1.22,E3(u)); ccx=lerp(W/2,GX+60,E3(u)); ccy=lerp(H/2,GY-210,E3(u)); }
  else if(ph==='cut'){ cz=1.22; ccx=GX+60; ccy=GY-210; }
  else if(ph==='glide'){ const u=seg(t,...TL.glide); pose=1; nx=lerp(GX,PX,EIO(u)); ny=GY-10*Math.sin(Math.PI*u); ghosts=[[nx-60,.18],[nx-120,.09]]; cz=lerp(1.12,1.0,u); ccx=lerp(GX+120,(PX+TX)/2,EIO(u)); ccy=GY-230; ck=7; }
  else if(ph==='palm'){ pose=2; nx=PX; cz=1.06; ccx=(PX+TX)/2; ccy=GY-230; ck=12; }
