function stepDrops(dt){ for(const p of WD){ p.t+=dt; p.vy+=p.g*dt; p.x+=p.vx*dt; p.y+=p.vy*dt; if(p.y>GY+6&&p.vy>0){ if(Math.random()<.35) ripple(p.x,GY+6,20+p.s*4,.45); p.t=p.life; } } WD=WD.filter(p=>p.t<p.life); for(const r of RP) r.t+=dt; RP=RP.filter(r=>r.t<r.life); }
