function motes(t,k){ if(k<=0) return; cx.save(); cx.globalCompositeOperation='lighter'; for(let i=0;i<60;i++){ const x=-200+rnd2(i)*(W+500)+Math.sin(t/700+i)*30, y=GY+20-((rnd2(i*5)*700+t*.06*(.5+rnd2(i*9)))%700); cx.globalAlpha=k*(.25+.5*rnd2(i*3)); cx.fillStyle=i%3?`rgb(${GOLD})`:`rgb(${ICE})`; cx.beginPath(); cx.arc(x,y,1.4+rnd2(i*7)*2.6,0,7); cx.fill(); } cx.restore(); }
