let WD=[]; function drops(x,y,n,o){ o=o||{}; for(let i=0;i<n;i++){ const an=(o.an!=null?o.an:-1.57)+(Math.random()-.5)*(o.spread||1.6), sp=(o.sp||500)*(.35+Math.random()*.9); WD.push({x:x+rnd(-(o.w||10),(o.w||10)),y:y-rnd(0,o.h||0),vx:Math.cos(an)*sp+(o.vx||0),vy:Math.sin(an)*sp,g:o.g==null?1500:o.g,s:rnd(o.s0||2.5,o.s1||6),t:0,life:rnd(.6,1.3)*(o.life||1)}); } }
