  if(t<SIX){ const up=E3(seg(t,TEE,TEE+120)), hold=seg(t,TEE+120,SIX-50), fall=EI3(seg(t,SIX-50,SIX)); let th=(1.36)*up+.06*Math.sin(hold*Math.PI*5)*(1-hold)*(hold>0?1:0); th=lerp(th,Math.PI/2,fall); return {k:'roll',x:x2+3*DSZ,th,face:FACES[3],teeter:1}; }
