  glow(d.x,GY-S/2,80+50*Math.sin((t-SIX)/60)**2+40*seg(t,SIX,FIN),.55+.35*seg(t,SIX+60,FIN),GOLD); if(t<SIX+300) gRings(d.x,GY,seg(t,SIX,SIX+300),130,.9);
