function fireBase(x,y,rx,a){ const g=cx.createRadialGradient(x,y,0,x,y,rx); g.addColorStop(0,`rgba(255,220,140,${.55*a})`); g.addColorStop(.5,`rgba(255,110,30,${.3*a})`); g.addColorStop(1,'rgba(255,60,0,0)'); cx.save(); cx.globalCompositeOperation='lighter'; cx.translate(x,y); cx.scale(1,.28); cx.translate(-x,-y); cx.fillStyle=g; cx.beginPath(); cx.arc(x,y,rx,0,7); cx.fill(); cx.restore(); }
// ── hand-drawn cel flame loop (8 frames, 391x351 each, base at the bottom-centre); front:true draws only the lower band so feet sit inside the fire
function fireLoop(x,y,w,t,a,o){ o=o||{}; const i=IM.fire_loop; if(!i||a<=0) return; const FW=391,FH=351, n=8, fps=o.fps||16, f=Math.floor((t/1000*fps+(o.ph||0)))%n, h=w*FH/FW*(o.sy||1);
  cx.save(); cx.globalAlpha=a; cx.translate(x,y); if(o.flip) cx.scale(-1,1); if(o.front){ cx.beginPath(); cx.rect(-w/2,-h*(o.front),w,h*o.front+4); cx.clip(); }
  cx.drawImage(i,f*FW,0,FW,FH,-w/2,-h,w,h); if(o.glow){ cx.globalCompositeOperation='lighter'; cx.globalAlpha=a*o.glow; cx.drawImage(i,f*FW,0,FW,FH,-w/2,-h,w,h); } cx.restore(); }

const vic=(p,x,y,o)=>{ const i=IM.riv; if(!i) return; o=o||{}; const h=300, s=h/i.height, w=i.width*s; let r=o.rot||0, dy=0, lit=0;
  if(p==='hurt') r+=.1; else if(p==='hit'){ r+=.16; lit=.45; } else if(p==='hit_h') lit=.3; else if(p==='down'){ r=1.5; dy=-w*.42; } if(o.tint) lit=Math.max(lit,.35);
  cx.save(); cx.globalAlpha=o.a==null?1:o.a; cx.translate(x,y+dy); cx.rotate(r); cx.scale(-1,1); if(o.sq) cx.scale(1+o.sq,1-o.sq); cx.drawImage(i,-w/2,-h,w,h); if(lit){ cx.globalCompositeOperation='lighter'; cx.globalAlpha*=lit; cx.drawImage(i,-w/2,-h,w,h); } cx.restore(); };


// Binder Dash (Lv1 Super: gain 6 Guard, deal 6). Amber plasma, white armour, lightning.
// systems online → cut-in → binders swing forward: a hex shield forms (guard) → thrusters roar, she rockets in behind the shield as a comet →
// shield bash (2) → beam saber slash (2) → binders snap forward like lances: piercing thrust (2) — electric explosion, rival blasted away →
// she hovers back on her thrusters, shield still humming, and lands.
const AMB='255,180,40', JADE=AMB, PINK=AMB, GOLD=AMB, ICE='255,230,170', PALE='255,248,225', VOLT=AMB, SKY=AMB, BK='tx_';
const TL={intro:[0,700],cut:[700,1500],guard:[1500,2050],boost:[2050,2300],bash:[2300,2560],s1:[2560,2900],s2:[2900,3240],s3:[3240,3640],thrust:[3640,4480],hover:[4480,5180],end:[5180,5980]}, END=6130;
const H1=2340, HS1=2640, HS2=2980, HS3=3320, FIN=3780;
const ZN=[[H1,H1+8,.1],[HS1,HS1+12,.1],[HS2,HS2+12,.1],[HS3,HS3+14,.09],[3660,FIN,.7],[FIN,FIN+14,.05],[FIN+14,FIN+700,.45]];
function r2s(tr){ let ts=0,tc=0; for(const z of ZN){ const gap=z[0]-ts; if(tr<tc+gap) return ts+(tr-tc); tc+=gap; ts=z[0]; const zr=(z[1]-z[0])/z[2]; if(tr<tc+zr) return ts+(tr-tc)*z[2]; tc+=zr; ts=z[1]; } return ts+(tr-tc); }
function s2r(t){ let ts=0,tc=0; for(const z of ZN){ if(t<=z[0]) return tc+(t-ts); tc+=z[0]-ts; ts=z[0]; if(t<=z[1]) return tc+(t-ts)/z[2]; tc+=(z[1]-z[0])/z[2]; ts=z[1]; } return tc+(t-ts); }
function rateAt(t){ for(const z of ZN) if(t>=z[0]&&t<z[1]) return z[2]; return 1; }
const GX=230, TX=900, GY=615, GH=405, SK=()=>GH/(IM.vk_1?IM.vk_1.height:312), PX=TX-230;
const MR=(n,x,y,o)=>{ o=Object.assign({},o); if(n==='G'){ if(!IM.valka_game) return; o.h=GH*1.05; spr('valka_game',x,y,o); return; } const k='vk_'+n, i=IM[k]; if(!i) return; o.h=i.height*SK(); spr(k,x,y,o); };
function rnd2(s){ const x=Math.sin(s*127.1+311.7)*43758.5453; return x-Math.floor(x); }
let SM=[]; function smoke(x,y,n,o){ o=o||{}; for(let i=0;i<n;i++) SM.push({x:x+rnd(-(o.w||40),(o.w||40)),y:y-rnd(0,o.h||10),vx:rnd(-30,30)+(o.vx||0),vy:-rnd(30,o.up||110),r:rnd(o.r0||14,o.r1||34),t:0,life:rnd(.6,1.2)}); }
function stepSmoke(dt){ const s=dt; for(const p of SM){ p.t+=s; p.x+=p.vx*s; p.y+=p.vy*s; p.r*=1+1.1*s; } SM=SM.filter(p=>p.t<p.life); }
function drawSmoke(){ for(const p of SM){ const k=p.t/p.life, a=(k<.2?k/.2:1-(k-.2)/.8)*.32; const g=cx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r); g.addColorStop(0,`rgba(220,240,255,${a*.7})`); g.addColorStop(.6,`rgba(140,200,240,${a*.4})`); g.addColorStop(1,'rgba(90,160,220,0)'); cx.fillStyle=g; cx.beginPath(); cx.arc(p.x,p.y,p.r,0,7); cx.fill(); } }
function impactFrame(w){ const s=w2s(w[0],w[1]); cx.save(); cx.globalCompositeOperation='difference'; cx.fillStyle='#fff'; cx.fillRect(0,0,W,H); cx.globalCompositeOperation='saturation'; cx.fillStyle='#000'; cx.fillRect(0,0,W,H); cx.restore();
  cx.save(); cx.fillStyle='#000'; for(let i=0;i<40;i++){ const an=i/40*6.283+rnd2(i)*0.1, r0=120+rnd2(i*3)*80, r1=1400, wd=.012+rnd2(i*7)*.02; cx.beginPath(); cx.moveTo(s[0]+Math.cos(an-wd)*r0,s[1]+Math.sin(an-wd)*r0); cx.lineTo(s[0]+Math.cos(an)*r1,s[1]+Math.sin(an)*r1); cx.lineTo(s[0]+Math.cos(an+wd)*r0,s[1]+Math.sin(an+wd)*r0); cx.fill(); } cx.restore(); }
// ---- debris: solid rocks/chunks with gravity (normal blending)
let DB=[]; function rocks(x,y,n,o){ o=o||{}; for(let i=0;i<n;i++){ const an=(o.an!=null?o.an:-1.57)+(Math.random()-.5)*(o.spread||1.6), sp=(o.sp||500)*(.4+Math.random()*.9); DB.push({x:x+rnd(-(o.w||20),(o.w||20)),y,vx:Math.cos(an)*sp+(o.vx||0),vy:Math.sin(an)*sp,g:o.g||1900,r:Math.random()*6,vr:rnd(-12,12),s:rnd(o.s0||4,o.s1||11),t:0,life:rnd(.7,1.3)*(o.life||1),c:Math.random()<.6?'#5a4330':(Math.random()<.5?'#8a6d4b':'#3d2e20'),gy:o.gy||GY+8,v:Array.from({length:5+(Math.random()*3|0)},(_,k,)=>[k,.55+Math.random()*.6])}); } }
function stepRocks(dt){ const s=dt; for(const p of DB){ p.t+=s; p.vy+=p.g*s; p.x+=p.vx*s; p.y+=p.vy*s; p.r+=p.vr*s; if(p.y>p.gy){ p.y=p.gy; p.vy*=-.3; p.vx*=.6; p.vr*=.5; } } DB=DB.filter(p=>p.t<p.life); }
function drawRocks(){ for(const p of DB){ cx.save(); cx.translate(p.x,p.y); cx.rotate(p.r); cx.globalAlpha=1-seg(p.t,p.life*.75,p.life); cx.fillStyle=p.c; cx.beginPath(); p.v.forEach(([k,r],i)=>{ const an=k/p.v.length*6.283, xx=Math.cos(an)*p.s*r, yy=Math.sin(an)*p.s*r*.8; i?cx.lineTo(xx,yy):cx.moveTo(xx,yy); }); cx.closePath(); cx.fill(); cx.strokeStyle='rgba(30,20,10,.8)'; cx.lineWidth=1.2; cx.stroke(); cx.restore(); } }
// ---- painted debris sprites (generated art): tumble, bounce, carried by wind
let DS=[]; const DBK=[1,2,3,4,5,6,7,10,12];
function debris(x,y,n,o){ o=o||{}; for(let i=0;i<n;i++){ const an=(o.an!=null?o.an:-1.57)+(Math.random()-.5)*(o.spread||1.4), sp=(o.sp||700)*(.45+Math.random()*.8); DS.push({k:'db_'+DBK[Math.random()*DBK.length|0],x:x+rnd(-(o.w||30),(o.w||30)),y:y-rnd(0,o.h||6),vx:Math.cos(an)*sp+(o.vx||0),vy:Math.sin(an)*sp,g:o.g||1700,r:Math.random()*6,vr:rnd(-9,9),s:rnd(o.s0||24,o.s1||70),t:0,life:rnd(1.1,1.8)*(o.life||1),gy:GY+6+rnd(-4,10),drag:o.drag||0,fl:Math.random()<.5}); } }
function stepDebris(dt){ for(const p of DS){ p.t+=dt; p.vy+=p.g*dt; p.vx*=1-p.drag*dt; p.x+=p.vx*dt; p.y+=p.vy*dt; p.r+=p.vr*dt; if(p.y>p.gy){ p.y=p.gy; p.vy*=-.28; p.vx*=.55; p.vr*=.5; } } DS=DS.filter(p=>p.t<p.life); }
function drawDebris(){ for(const p of DS){ const im=IM[p.k]; if(!im) continue; const h=p.s, w=h*im.width/im.height; cx.save(); cx.translate(p.x,p.y-h*.3); cx.rotate(p.r); if(p.fl) cx.scale(-1,1); cx.globalAlpha=1-seg(p.t,p.life*.8,p.life); cx.drawImage(im,-w/2,-h/2,w,h); cx.restore(); } }
const GL=.72;
function blast(x,y,u,size,al){ if(u<0||u>=1) return; const f=Math.min(7,Math.floor(u*8)), fu=u*8-f, im=IM[BK+(f+1)], im2=IM[BK+Math.min(8,f+2)]; if(!im) return; const h=size, w=h*im.width/im.height; cx.save(); cx.globalCompositeOperation='lighter';
  cx.globalAlpha=al*(1-fu*.5); cx.drawImage(im,x-w/2,y-h*GL,w,h); if(im2&&f<7){ cx.globalAlpha=al*fu*.6; cx.drawImage(im2,x-w/2,y-h*GL,w,h); } cx.restore(); }
// ---- heavy swing: tapered crescent following the blade tip (thin tail → thick head), optional flattening for horizontal swings
function heavyArc(x,y,R,a0,a1,u,w,sy){ if(u<=0||u>=1) return; const head=E3(cl(u/.28)), tail=E3(seg(u,.22,1)); if(head<=tail+.01) return; const N=28, fade=1-seg(u,.5,1);
  const pts=(rIn,wk)=>{ const o=[], inn=[]; for(let k=0;k<=N;k++){ const f=k/N, s2=lerp(tail,head,f), an=lerp(a0,a1,s2), ww=w*wk*Math.pow(f,1.3); o.push([Math.cos(an)*R,Math.sin(an)*R]); inn.push([Math.cos(an)*(R-ww),Math.sin(an)*(R-ww)]); } return o.concat(inn.reverse()); };
  cx.save(); cx.translate(x,y); cx.scale(1,sy||1); cx.globalCompositeOperation='lighter';
  for(const [wk,al,col,bl] of [[2.2,.14,GOLD,30],[1,.45,'255,214,120',18],[.3,.75,'255,250,230',8]]){ const P=pts(R,wk); cx.beginPath(); P.forEach((p,k)=>k?cx.lineTo(p[0],p[1]):cx.moveTo(p[0],p[1])); cx.closePath(); cx.fillStyle=`rgba(${col},${al*fade})`; cx.shadowColor=`rgb(${GOLD})`; cx.shadowBlur=bl; cx.fill(); }
  // speed streaks trailing behind the edge
  cx.strokeStyle=`rgba(255,240,200,${.5*fade})`; cx.lineWidth=2; for(let k=0;k<6;k++){ const an=lerp(a0,a1,lerp(tail,head,.3+k*.1)), r=R+6+k*3; cx.beginPath(); cx.arc(0,0,r,an-(a1>a0?.35:-.35),an,a1<a0); cx.stroke(); }
  cx.restore(); }
// ---- ground cracks around a crater
