  let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9; for(const p of B){ const R=p.r*3; x0=Math.min(x0,p.x-R); y0=Math.min(y0,p.y-R*2); x1=Math.max(x1,p.x+R); y1=Math.max(y1,p.y+R); }
  const w=Math.ceil((x1-x0)*S)+2, h=Math.ceil((y1-y0)*S)+2; if(w<2||h<2||w*h>900000) return; _fc.width=w; _fc.height=h;
