function orb(x,y,r,a,col){ if(a<=0) return; cx.save(); cx.globalCompositeOperation='lighter'; const g=cx.createRadialGradient(x,y,0,x,y,r*2.6); g.addColorStop(0,`rgba(255,255,255,${a})`); g.addColorStop(.3,`rgba(${col||JADE},${a*.8})`); g.addColorStop(1,`rgba(${col||JADE},0)`); cx.fillStyle=g; cx.beginPath(); cx.arc(x,y,r*2.6,0,7); cx.fill(); cx.restore(); }
