  SH.forEach((s,i)=>{ if(t>=s+180) once('s'+i,()=>{ spawn(8,{x:attachPt(i,RX,RY,vr)[0],y:attachPt(i,RX,RY,vr)[1],sp:200,g:300,life:.5,s:2,k:'dot',c:'#ff5a6e'}); }); });
  if(t>=SNIP) once('snip',()=>{ shake(8,200); });
