// ---- ground ripple rings around a point
function rings(x,y,u,R,a){ if(u<=0||a<=0) return; cx.save(); for(let k=0;k<3;k++){ const v=(u*1.3+k/3)%1, r=R*E3(v); cx.globalAlpha=a*(1-v); cx.strokeStyle=k%2?'rgb(150,220,255)':'rgb(235,250,255)'; cx.lineWidth=3*(1-v)+1; cx.beginPath(); cx.ellipse(x,y,r,r*.2,0,0,7); cx.stroke(); } cx.restore(); }
// ---- geyser / wave frames (alpha water art), bottom-anchored on the ground
function wfx(pre,x,y,u,size,al,flip){ if(u<0||u>=1) return; const f=Math.min(7,Math.floor(u*8)), fu=u*8-f, im=IM[pre+(f+1)], im2=IM[pre+Math.min(8,f+2)]; if(!im) return; const h=size, w=h*im.width/im.height;
  cx.save(); if(flip){ cx.translate(x,0); cx.scale(-1,1); cx.translate(-x,0); } cx.globalAlpha=al*(1-fu*.45); cx.drawImage(im,x-w/2,y-h*.937,w,h); if(im2&&f<7){ cx.globalAlpha=al*fu*.55; cx.drawImage(im2,x-w/2,y-h*.937,w,h); } cx.restore(); }
// ---- spiralling water streams (ribbons) rising around a point; k = 0..1 progress, conv = how far they've wrapped in
function streams(x,y,t,k,R,Hh,a){ if(a<=0) return; cx.save(); for(let s=0;s<4;s++){ const ph=s*1.5708+t/260; cx.beginPath(); const N=30; for(let i=0;i<=N;i++){ const f=i/N; if(f>k) break; const an=ph+f*7, r=R*(1-.35*f), xx=x+Math.cos(an)*r, yy=y-f*Hh+Math.sin(an)*r*.22; i?cx.lineTo(xx,yy):cx.moveTo(xx,yy); }
  cx.lineCap='round'; cx.strokeStyle=`rgba(90,190,255,${.55*a})`; cx.lineWidth=16; cx.stroke(); cx.strokeStyle=`rgba(200,245,255,${.9*a})`; cx.lineWidth=5; cx.stroke(); } cx.restore(); }
// ---- water dome shield: translucent bubble with a bright rim, moving caustic highlights and a wobbling surface
function dome(x,y,u,a,t){ if(u<=0||a<=0) return; const R=190*E3(u), Hh=250*E3(u); cx.save(); cx.globalAlpha=a; const wob=k=>1+.025*Math.sin(t/140+k*3);
  cx.beginPath(); for(let i=0;i<=40;i++){ const an=Math.PI+i/40*Math.PI, rr=wob(i/40); const xx=x+Math.cos(an)*R*rr, yy=y+Math.sin(an)*Hh*rr; i?cx.lineTo(xx,yy):cx.moveTo(xx,yy); } cx.closePath();
  const g=cx.createRadialGradient(x,y-Hh*.45,Hh*.2,x,y-Hh*.4,Hh*1.1); g.addColorStop(0,'rgba(140,220,255,.05)'); g.addColorStop(.7,'rgba(90,190,255,.22)'); g.addColorStop(1,'rgba(200,245,255,.55)'); cx.fillStyle=g; cx.fill();
  cx.lineWidth=5; cx.strokeStyle='rgba(220,250,255,.85)'; cx.stroke(); cx.lineWidth=14; cx.strokeStyle='rgba(90,190,255,.25)'; cx.stroke();
  cx.globalCompositeOperation='lighter'; for(let i=0;i<5;i++){ const an=Math.PI*1.15+((t/900+i/5)%1)*Math.PI*.7; cx.strokeStyle=`rgba(235,250,255,${.5})`; cx.lineWidth=3; cx.beginPath(); cx.ellipse(x,y,R*.82,Hh*.82,0,an,an+.35); cx.stroke(); }
  cx.globalCompositeOperation='source-over'; cx.fillStyle='rgba(255,255,255,.7)'; cx.beginPath(); cx.ellipse(x-R*.42,y-Hh*.7,R*.12,Hh*.05,-.6,0,7); cx.fill();
  cx.strokeStyle='rgba(200,245,255,.6)'; cx.lineWidth=2.5; cx.beginPath(); cx.ellipse(x,y,R*1.05,R*.18,0,0,7); cx.stroke(); cx.restore(); }
function gather(t,x,y,k){ if(k<=0) return; cx.save(); for(let i=0;i<26;i++){ const an=rnd2(i)*6.283+t/600, r=(1-((t/900+rnd2(i*3))%1))*220, xx=x+Math.cos(an)*r, yy=y-60-rnd2(i*7)*200+Math.sin(an)*r*.3; cx.globalAlpha=k*(.4+.5*rnd2(i*5)); cx.fillStyle=i%3?'rgb(150,225,255)':'rgb(240,252,255)'; cx.beginPath(); cx.arc(xx,yy,2+rnd2(i*9)*3.5,0,7); cx.fill(); } cx.restore(); }

