// audio cue track: [scene ms (or "r"+real ms), sound, align mode, gain dB]

// additive bottom-anchored effect frames (lightning strike sheet)
function efx(pre,x,y,u,size,al){ if(u<0||u>=1) return; const f=Math.min(7,Math.floor(u*8)), fu=u*8-f, im=IM[pre+(f+1)], im2=IM[pre+Math.min(8,f+2)]; if(!im) return; const h=size, w=h*im.width/im.height;
  cx.save(); cx.globalCompositeOperation='lighter'; cx.globalAlpha=al*(1-fu*.45); cx.drawImage(im,x-w/2,y-h*.937,w,h); if(im2&&f<7){ cx.globalAlpha=al*fu*.55; cx.drawImage(im2,x-w/2,y-h*.937,w,h); } cx.restore(); }


// glowing orb
function orb(x,y,r,a,col){ if(a<=0) return; cx.save(); cx.globalCompositeOperation='lighter'; const g=cx.createRadialGradient(x,y,0,x,y,r*2.6); g.addColorStop(0,`rgba(255,255,255,${a})`); g.addColorStop(.3,`rgba(${col||JADE},${a*.8})`); g.addColorStop(1,`rgba(${col||JADE},0)`); cx.fillStyle=g; cx.beginPath(); cx.arc(x,y,r*2.6,0,7); cx.fill(); cx.restore(); }
// a soft ribbon / thread from (x0,y0) to (x1,y1) that waves
function ribbon(x0,y0,x1,y1,t,a,w,col,amp,ph){ if(a<=0) return; cx.save(); cx.globalCompositeOperation='lighter'; cx.lineCap='round'; const N=26; const pts=[]; for(let i=0;i<=N;i++){ const f=i/N, nx=-(y1-y0), ny=(x1-x0), L=Math.hypot(nx,ny)||1; const off=Math.sin(f*Math.PI)*Math.sin(f*7+t/120+(ph||0))*(amp||30); pts.push([lerp(x0,x1,f)+nx/L*off, lerp(y0,y1,f)+ny/L*off]); }
  for(const [ww,al,c] of [[w*3,.25,col||PINK],[w,.75,col||PINK],[w*.35,.95,'255,255,255']]){ cx.strokeStyle=`rgba(${c},${a*al})`; cx.lineWidth=ww; cx.beginPath(); pts.forEach((p,i)=>i?cx.lineTo(p[0],p[1]):cx.moveTo(p[0],p[1])); cx.stroke(); } cx.restore(); }
