function celRing(em,x,y,rx,inten,dt){ const n=Math.max(1,Math.round(dt*330*inten)); em.emit({x,y,ring:{rx,ry:rx*.2},r:12+8*inten,n,up:420+320*inten,life:.26+.14*inten,jx:30}); if(Math.random()<.5) em.emit({x,y:y-4,w:rx*1.3,r:16+10*inten,n:1,up:600+400*inten,life:.34,jx:40,back:1}); }
