// additive bottom-anchored effect frames (lightning strike sheet)
function efx(pre,x,y,u,size,al){ if(u<0||u>=1) return; const f=Math.min(7,Math.floor(u*8)), fu=u*8-f, im=IM[pre+(f+1)], im2=IM[pre+Math.min(8,f+2)]; if(!im) return; const h=size, w=h*im.width/im.height;
  cx.save(); cx.globalCompositeOperation='lighter'; cx.globalAlpha=al*(1-fu*.45); cx.drawImage(im,x-w/2,y-h*.937,w,h); if(im2&&f<7){ cx.globalAlpha=al*fu*.55; cx.drawImage(im2,x-w/2,y-h*.937,w,h); } cx.restore(); }


// glowing orb
function orb(x,y,r,a,col){ if(a<=0) return; cx.save(); cx.globalCompositeOperation='lighter'; const g=cx.createRadialGradient(x,y,0,x,y,r*2.6); g.addColorStop(0,`rgba(255,255,255,${a})`); g.addColorStop(.3,`rgba(${col||JADE},${a*.8})`); g.addColorStop(1,`rgba(${col||JADE},0)`); cx.fillStyle=g; cx.beginPath(); cx.arc(x,y,r*2.6,0,7); cx.fill(); cx.restore(); }
// a soft ribbon / thread from (x0,y0) to (x1,y1) that waves
function ribbon(x0,y0,x1,y1,t,a,w,col,amp,ph){ if(a<=0) return; cx.save(); cx.globalCompositeOperation='lighter'; cx.lineCap='round'; const N=26; const pts=[]; for(let i=0;i<=N;i++){ const f=i/N, nx=-(y1-y0), ny=(x1-x0), L=Math.hypot(nx,ny)||1; const off=Math.sin(f*Math.PI)*Math.sin(f*7+t/120+(ph||0))*(amp||30); pts.push([lerp(x0,x1,f)+nx/L*off, lerp(y0,y1,f)+ny/L*off]); }
  for(const [ww,al,c] of [[w*3,.25,col||PINK],[w,.75,col||PINK],[w*.35,.95,'255,255,255']]){ cx.strokeStyle=`rgba(${c},${a*al})`; cx.lineWidth=ww; cx.beginPath(); pts.forEach((p,i)=>i?cx.lineTo(p[0],p[1]):cx.moveTo(p[0],p[1])); cx.stroke(); } cx.restore(); }
// threads coiling around the rival's body
function coil(x,y,t,a){ if(a<=0) return; cx.save(); cx.globalCompositeOperation='lighter'; for(let k=0;k<3;k++){ cx.strokeStyle=`rgba(${k%2?JADE:PINK},${.7*a})`; cx.lineWidth=4; cx.beginPath(); for(let i=0;i<=40;i++){ const f=i/40, an=f*12+t/180+k*2, yy=y-40-f*230; const xx=x+Math.cos(an)*70; i?cx.lineTo(xx,yy+Math.sin(an)*14):cx.moveTo(xx,yy+Math.sin(an)*14); } cx.stroke(); } cx.restore(); }
function bloom(x,y,u,a){ if(u<=0||u>=1) return; cx.save(); cx.globalCompositeOperation='lighter'; for(let k=0;k<3;k++){ const v=Math.max(0,u-k*.15); if(v<=0) continue; cx.globalAlpha=a*(1-v); cx.strokeStyle=k%2?`rgb(${PINK})`:`rgb(${JADE})`; cx.lineWidth=4*(1-v)+1; cx.beginPath(); cx.ellipse(x,y,260*E3(v),260*E3(v)*.26,0,0,7); cx.stroke(); }
  for(let i=0;i<8;i++){ const an=i/8*6.283, r=40+120*E3(u); const px=x+Math.cos(an)*r*.9, py=y-160+Math.sin(an)*r*.6; cx.globalAlpha=a*(1-u); cx.fillStyle=`rgb(${i%2?PINK:JADE})`; cx.beginPath(); cx.ellipse(px,py,9,4,an,0,7); cx.fill(); } cx.restore(); }
// life orbs: ripped out of the rival, then streaming into her hands
function ssx(x,y,u,size,al){ if(u<=0||u>=1) return; const f=Math.min(7,Math.floor(u*8)), fu=u*8-f, im=IM['ss_'+(f+1)], im2=IM['ss_'+Math.min(8,f+2)]; if(!im) return; const h=size, w=h*im.width/im.height;
  cx.save(); cx.globalCompositeOperation='lighter'; cx.globalAlpha=al*(1-fu*.45); cx.drawImage(im,x-w/2,y-h*.9,w,h); if(im2&&f<7){ cx.globalAlpha=al*fu*.55; cx.drawImage(im2,x-w/2,y-h*.9,w,h); } cx.restore(); }
function fxs(pre,x,y,u,h,al,o){ if(u<=0||u>=1||al<=0) return; o=o||{}; const f=Math.min(7,Math.floor(u*8)), fu=u*8-f, im=IM[pre+(f+1)], im2=IM[pre+Math.min(8,f+2)]; if(!im) return; const w=h*im.width/im.height, ay=o.bot?h*.93:h/2;
  cx.save(); cx.globalCompositeOperation=o.op||'lighter'; cx.translate(x,y); if(o.rot) cx.rotate(o.rot); cx.scale(o.fx?-1:1,o.fy?-1:1);
  cx.globalAlpha=al*(1-fu*.45); cx.drawImage(im,-w/2,-ay,w,h); if(im2&&f<7){ cx.globalAlpha=al*fu*.55; cx.drawImage(im2,-w/2,-ay,w,h); } cx.restore(); }
function fxl(pre,x,y,t,h,al,ms){ if(al<=0) return; const f=Math.floor(t/(ms||70))%8, im=IM[pre+(f+1)]; if(!im) return; const w=h*im.width/im.height; cx.save(); cx.globalCompositeOperation='lighter'; cx.globalAlpha=al; cx.drawImage(im,x-w/2,y-h*.77,w,h); cx.restore(); }
function wisps(x,y,t,k,h){ if(k<=0) return; cx.save(); for(let i=0;i<18;i++){ const f=((t/600)+rnd2(i*5))%1, xx=x+(rnd2(i)-.5)*120+Math.sin(t/200+i)*10, yy=y-f*(h||260); cx.globalAlpha=k*(1-f)*.55; cx.fillStyle=i%3?'rgba(8,8,20,1)':`rgba(${SHD},1)`; cx.beginPath(); cx.ellipse(xx,yy,10+rnd2(i*3)*10,16+rnd2(i*7)*14,0,0,7); cx.fill(); } cx.restore(); glow(x,y-100,140,.25*k,SHD); }
function buff(t,t0,txt,label,col,x,y){ if(t<t0) return; const u=seg(t,t0,t0+1500); cx.save(); const s=lerp(2,1,E3(seg(u,0,.14))); cx.translate(x,y-30*u); cx.scale(s,s); cx.globalAlpha=1-seg(u,.82,1); cx.textAlign='center';
  cx.font='italic 900 56px Impact, sans-serif'; cx.lineWidth=10; cx.strokeStyle='#111'; cx.strokeText(txt,0,0); cx.fillStyle=col; cx.fillText(txt,0,0); if(label){ cx.font='900 24px Impact, sans-serif'; cx.lineWidth=6; cx.strokeText(label,0,34); cx.fillStyle='#fff'; cx.fillText(label,0,34); } cx.restore(); }
